import { z } from "zod";

// ─── Application-Level Category Constants ────────────────────────────────────

/**
 * SYSTEM_CATEGORIES are auto-generated by RPCs and must never be
 * selected manually in Create/Update forms.
 */
export const SYSTEM_EXPENSE_CATEGORIES = ["FEED_PURCHASE"] as const;

/**
 * MANUAL_CATEGORIES are the only options available in the expense form.
 */
export const MANUAL_EXPENSE_CATEGORIES = [
  "MEDICATION",
  "UTILITIES",
  "EQUIPMENT",
  "MAINTENANCE",
  "PACKAGING",
  "VETERINARY",
  "LABOR",
  "OTHER",
] as const;

/**
 * ALL_EXPENSE_CATEGORIES — for display and filter purposes only.
 */
export const ALL_EXPENSE_CATEGORIES = [
  ...SYSTEM_EXPENSE_CATEGORIES,
  ...MANUAL_EXPENSE_CATEGORIES,
] as const;

export type SystemExpenseCategory = (typeof SYSTEM_EXPENSE_CATEGORIES)[number];
export type ManualExpenseCategory = (typeof MANUAL_EXPENSE_CATEGORIES)[number];
export type ExpenseCategory = (typeof ALL_EXPENSE_CATEGORIES)[number];

/** Human-readable labels for display */
export const EXPENSE_CATEGORY_LABELS: Record<string, string> = {
  FEED_PURCHASE: "Feed Purchase",
  MEDICATION: "Medication",
  UTILITIES: "Utilities",
  EQUIPMENT: "Equipment",
  MAINTENANCE: "Maintenance",
  PACKAGING: "Packaging",
  VETERINARY: "Veterinary",
  LABOR: "Labor",
  OTHER: "Other",
};

/**
 * Returns true when a category string represents an auto-generated expense.
 * The UI should hide edit/delete controls for these records.
 */
export function isSystemCategory(category: string): boolean {
  return (SYSTEM_EXPENSE_CATEGORIES as readonly string[]).includes(category);
}

// ─── Create Expense Schema ────────────────────────────────────────────────────
// NOTE: Uses Zod v4 API — z.enum() takes { message } not { errorMap }
//                        — z.number() takes { message } not { required_error }
//                        — parse errors are in .issues not .errors

export const createExpenseSchema = z.object({
  expense_date: z
    .string()
    .min(1, "Expense date is required.")
    .refine((d) => !isNaN(Date.parse(d)), "Please enter a valid date."),

  // Zod v4: z.enum accepts a readonly tuple, params use { message }
  category: z.enum(
    [
      "MEDICATION",
      "UTILITIES",
      "EQUIPMENT",
      "MAINTENANCE",
      "PACKAGING",
      "VETERINARY",
      "LABOR",
      "OTHER",
    ] as const,
    {
      message: "Please select a valid expense category.",
    }
  ),

  // Zod v4: z.number() params use { message }
  amount: z
    .number({ message: "Amount must be a number." })
    .positive("Amount must be greater than zero.")
    .max(9_999_999_999.99, "Amount exceeds the maximum allowed value."),

  description: z
    .string()
    .trim()
    .max(500, "Description must be at most 500 characters.")
    .optional()
    .or(z.literal("")),

  supplier_id: z
    .string()
    .uuid("Invalid supplier selected.")
    .nullable()
    .optional(),
});

// ─── Update Expense Schema ────────────────────────────────────────────────────

export const updateExpenseSchema = z.object({
  expense_date: z
    .string()
    .min(1, "Expense date is required.")
    .refine((d) => !isNaN(Date.parse(d)), "Please enter a valid date."),

  category: z.enum(
    [
      "MEDICATION",
      "UTILITIES",
      "EQUIPMENT",
      "MAINTENANCE",
      "PACKAGING",
      "VETERINARY",
      "LABOR",
      "OTHER",
    ] as const,
    {
      message: "Please select a valid expense category.",
    }
  ),

  amount: z
    .number({ message: "Amount must be a number." })
    .positive("Amount must be greater than zero.")
    .max(9_999_999_999.99, "Amount exceeds the maximum allowed value."),

  description: z
    .string()
    .trim()
    .max(500, "Description must be at most 500 characters.")
    .optional()
    .or(z.literal("")),

  supplier_id: z
    .string()
    .uuid("Invalid supplier selected.")
    .nullable()
    .optional(),
});

export type CreateExpenseInput = z.infer<typeof createExpenseSchema>;
export type UpdateExpenseInput = z.infer<typeof updateExpenseSchema>;
